var i=[{title:`Rudertechnik`,text:`Beginne in einer stabilen Position und ziehe je nach Übung zu den unteren Rippen oder zur Hüfte. Lass die Schulterblätter sich natürlich bewegen, wenn die Arme nach vorn greifen und zurückziehen, und schwinge den Oberkörper nicht, um Schwung zu holen. Du musst deine Ellenbogen nicht in einen Winkel zwingen, und der Bewegungsumfang endet dort, wo du ihn noch kontrollieren kannst.`},{title:`Geräte-Variationen`,text:`Ein einarmiges Kurzhantelrudern arbeitet jede Seite für sich, und du kannst zur Stütze eine Hand auf eine sichere Bank legen. Beim sitzenden Kabelrudern kannst du die Last in kleinen Schritten anpassen. Bandrudern braucht einen sicheren Anker, und der Widerstand verändert sich im Verlauf der Wiederholung. Umgekehrtes Rudern mit Körpergewicht wird leichter, je aufrechter dein Körper ist, und schwerer, je näher er der Waagerechten kommt.`},{title:`Was die Schwierigkeit verändert`,text:`Oberkörperwinkel, Stütze, Griffbreite, Ellenbogenweg, Last und Bewegungsumfang verändern, wie schwer ein Rudern ist. Ein brustgestütztes Rudern nimmt dir das Halten eines vorgebeugten Hüftbeugens ab, was hilft, wenn du deinen Rücken trainieren willst und nicht die Ausdauer deiner Beugung. Es ist auch eine gute Wahl, wenn dir langes Halten in einer Beuge nicht liegt. Halte verschiedene Ruder-Varianten getrennt fest, da ihre Zahlen nicht austauschbar sind.`},{title:`Typische Fehler`,text:`Vermeide starkes Schulterzucken, Rucken mit dem unteren Rücken oder einen verkürzten Bewegungsumfang, nur um mehr zu heben. Wenn deine Position verrutscht, verringere die Last und verlangsame die Absenkphase. Ruderübungen zu Hause mit einem Tisch oder einem Handtuch sind nur sicher, wenn Anker und Konstruktion dein bewegtes Körpergewicht verlässlich halten.`},{title:`Deine Woche planen`,text:`Kombiniere Rudern über die Woche mit horizontalen Drückübungen. Wähle Ruder-Varianten, die zu deiner Ausrüstung, zu der Stelle, an der du ein Band sicher verankern kannst, und zu den Lasten passen, die du hast.`}];var r=[{label:`ACE-Übungsbibliothek`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`Mayo Clinic: Technik beim Krafttraining (2026)`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`},{label:`NSCA: Sicherheit und Grundlagen des Krafttrainings`,url:`https://www.nsca.com/education/articles/ptq/the-safest-and-riskiest-forms-of-resistance-training/`}];var t={sections:i,sources:r};export{t as default,i as sections,r as sources};